#!/usr/bin/env python3
"""Stress the quota-constrained planner against brute force and NetworkX."""
import collections, ipaddress, random, sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/deps')
sys.path.insert(0, '/workspace/tools')

import planning
import networkx as nx
from networkx.algorithms.flow import max_flow_min_cost

DOC = ipaddress.IPv6Network('2001:db8::/32')


def forest(rng, prefix, count, caps=(1, 2, 3, 5, 4096)):
    nodes, table = [], {}
    for index in range(count):
        name = '%s%d' % (prefix, index)
        parent = None
        if index and rng.random() < .6:
            candidate = nodes[rng.randrange(index)]['id']
            depth, walk = 0, candidate
            while walk is not None:
                depth += 1
                walk = table[walk]['parent']
            if depth < 6:
                parent = candidate
        node = {'id': name, 'parent': parent, 'capacity': rng.choice(list(caps))}
        table[name] = node
        nodes.append(node)
    rng.shuffle(nodes)
    return nodes, table


def make_case(rng, nrequests=8, noffers=6, nquota=3):
    requests, offers = {}, {}
    leases = {'L%d' % i: {'end': 10 ** 6} for i in range(3)}
    queries = [10, 20, 30]
    services = {'S0': 'tcp', 'S1': 'adb', 'S2': 'sync'}
    rq, rq_table = forest(rng, 'Q', nquota)
    oq, oq_table = forest(rng, 'O', nquota)
    targets = []
    for index in range(nrequests):
        value = int(DOC.network_address) + rng.randrange(1, 1 << 90)
        targets.append(value)
        name = 'R%d' % index
        requests[name] = {'id': name, 'at': rng.choice(queries),
                          'lease': 'L%d' % rng.randrange(3), 'service': rng.choice(list(services)),
                          'group': rng.choice([q['id'] for q in rq]) if rq else 'all',
                          'address': value}
    listed = collections.defaultdict(list)
    for index in range(noffers):
        name = 'F%d' % index
        service = rng.choice(list(services))
        pick = [key for key, row in requests.items() if row['service'] == service]
        subset = rng.sample(pick, rng.randrange(0, len(pick) + 1)) if pick else []
        for key in subset:
            listed[name].append(key)
        bits = rng.choice([32, 56, 64, 90, 128])
        if subset:
            value = requests[rng.choice(subset)]['address']
        else:
            value = rng.choice(targets)
        step = 1 << (128 - bits)
        network = ipaddress.IPv6Network((((int(DOC.network_address) + (value - int(DOC.network_address)))
                                          // step) * step, bits))
        offers[name] = {'id': name, 'time': rng.choice(queries + [15, 25]),
                        'service': service, 'network': network,
                        'capacity': rng.choice([1, 1, 2, 3, 4096]),
                        'cost': rng.choice([0, 1, 2, 3, 17, 1000]),
                        'group': rng.choice([q['id'] for q in oq]) if oq else 'all',
                        'requests': subset,
                        'prefix': str(network)}
    active = {key: rng.random() < .75 for key in requests}
    context = {'leases': leases, 'services': services, 'requests': requests,
               'offers': offers, 'request_quotas': rq, 'request_paths': paths(rq),
               'offer_quotas': oq, 'offer_paths': paths(oq)}
    return context, active


def paths(nodes):
    table = {node['id']: node for node in nodes}
    out = {}
    for node in nodes:
        chain = []
        walk = node['id']
        while walk is not None:
            chain.append(walk)
            walk = table[walk]['parent']
        out[node['id']] = tuple(chain)
    return out


def networkx_cost(context, active):
    """Reference min-cost max-flow through NetworkX, with the same model."""
    pairs = planning._reachable_pairs(context, active)
    G = nx.MultiDiGraph()
    source, sink = 'source', 'sink'
    for name, capacity in [('source', None), ('sink', None)]:
        pass
    for key, index in context['request_paths'].items():
        node = 'rq:' + key
        capacity = context['request_quotas'][key]['capacity']
        parent = context['request_quotas'][key]['parent']
        head = source if parent is None else 'rq:' + parent
        G.add_edge(head, node, capacity=capacity, weight=0)
    for key, index in context['offer_paths'].items():
        node = 'oq:' + key
        capacity = context['offer_quotas'][key]['capacity']
        parent = context['offer_quotas'][key]['parent']
        tail = sink if parent is None else 'oq:' + parent
        G.add_edge(node, tail, capacity=capacity, weight=0)
    used_requests = set()
    used_offers = set()
    for offer_id, rows in pairs.items():
        for request_id, _ in rows:
            used_requests.add(request_id)
            used_offers.add(offer_id)
    for request_id in used_requests:
        group = context['requests'][request_id]['group']
        G.add_edge('rq:' + group, 'r:' + request_id, capacity=1, weight=0)
    for offer_id in used_offers:
        offer = context['offers'][offer_id]
        G.add_edge('o:' + offer_id, 'oq:' + offer['group'],
                   capacity=offer['capacity'], weight=offer['cost'])
    for offer_id, rows in pairs.items():
        for request_id, _ in rows:
            G.add_edge('r:' + request_id, 'o:' + offer_id, capacity=1, weight=0)
    try:
        flow = max_flow_min_cost(G, source, sink)
    except nx.NetworkXUnfeasible:
        return 0, 0
    total = 0
    value = 0
    for u, v, data in G.edges(data=True):
        arc = data.get('flow', 0)
        if u == source:
            value += arc
        total += arc * data.get('weight', 0)
    return value, total


def main():
    count = int(sys.argv[1]) if len(sys.argv) > 1 else 40
    bad = 0
    for case in range(count):
        rng = random.Random(case + 1000)
        context, active = make_case(rng, rng.randrange(1, 9), rng.randrange(1, 7),
                                    rng.randrange(0, 4))
        got = planning.solve(context, active)
        value, cost = networkx_cost(context, active)
        if got['resolved'] != value or got['cost'] != cost:
            print('case', case, 'MISMATCH mine', got['resolved'], got['cost'],
                  'networkx', value, cost)
            bad += 1
            continue
        # verify the produced plan satisfies every constraint
        if not verify(context, active, got):
            print('case', case, 'INVALID plan')
            bad += 1
    print('plan fuzz done, failures =', bad, 'of', count)
    return 1 if bad else 0


def verify(context, active, plan):
    used_r, used_o, rquota, oquota, total = set(), collections.Counter(), \
        collections.Counter(), collections.Counter(), 0
    for row in plan['assignments']:
        request = context['requests'][row['request']]
        offer = context['offers'][row['offer']]
        if not active.get(row['request']) or row['request'] in used_r:
            return False
        used_r.add(row['request'])
        used_o[row['offer']] += 1
        if request['service'] != offer['service']:
            return False
        if not (request['at'] <= offer['time'] < context['leases'][request['lease']]['end']):
            return False
        if not (int(offer['network'].network_address) <= request['address']
                < int(offer['network'].network_address)
                + (1 << (128 - offer['network'].prefixlen))):
            return False
        if row['request'] not in offer['requests']:
            return False
        for node in context['request_paths'][request['group']]:
            rquota[node] += 1
        for node in context['offer_paths'][offer['group']]:
            oquota[node] += 1
        total += offer['cost']
    for offer_id, count_ in used_o.items():
        if count_ > context['offers'][offer_id]['capacity']:
            return False
    for node, count_ in rquota.items():
        if count_ > context['request_quotas'][node]['capacity']:
            return False
    for node, count_ in oquota.items():
        if count_ > context['offer_quotas'][node]['capacity']:
            return False
    if total != plan['cost'] or len(plan['assignments']) != plan['resolved']:
        return False
    keys = [row['request'] for row in plan['assignments']]
    return keys == sorted(keys)


if __name__ == '__main__':
    sys.exit(main())
